-- ============================================================
-- FT 设备类型增量脚本：补全/更新已有映射，并插入未覆盖的 FT 类型
-- 适用于已经导入 current 目录的数据库。
-- ============================================================

-- 1. 补全空映射 / 更新已不存在的 FT code
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"295"}]', update_time = NOW() WHERE code = 'EFDWDIP';  -- 探测绝缘性能式电气火灾探测器
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"2"}]', update_time = NOW() WHERE code = 'currencyDevice';  -- 未识别设备
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"147"}]', update_time = NOW() WHERE code = 'FAD';  -- 故障电弧探测器
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"181"}]', update_time = NOW() WHERE code = 'FRD';  -- 防火卷帘门
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"213"}]', update_time = NOW() WHERE code = 'RPMD';  -- 余压监控探测器: 374 -> 213
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"301"}]', update_time = NOW() WHERE code = 'FPCUT';  -- 电源强切: 146 -> 301
UPDATE za_device_type SET aliases = '[{"pfCode":"ft","alias":"307"}]', update_time = NOW() WHERE code = 'UITD';  -- 用户信息传输装置: 128 -> 307

-- 2. 插入尚未接入的 FT 设备类型
ON DUPLICATE KEY UPDATE name = VALUES(name), aliases = VALUES(aliases), update_time = NOW();
